    def numFactoredBinaryTrees(self, A: List[int]) -> int:
        A.sort()
        dp = {}
        for i in range(len(A)):
            dp[A[i]] = 1
            for j in range(i):
                if A[i] % A[j] == 0:
                    if A[i] // A[j] in dp:
                        dp[A[i]] += dp[A[j]] * dp[A[i] // A[j]]
        return sum(dp.values()) % (10 ** 9 + 7)
